import sys

MOD = 998244353

def count_chaotic_merges(x, y):
    n, m = len(x), len(y)
    dp = [[[0] * (m + 1) for _ in range(n + 1)] for __ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j][0] = 1
            dp[i][j][1] = 1

    for i in range(1, n + 1):
        for l in range(1, m + 1):
            for r in range(2, l + 1):
                dp[i][l][r] = dp[i][l - 1][r - 1]
                if x[i - 1] != y[l - r]:
                    dp[i][l][r] += dp[i - 1][l][r]
                dp[i][l][r] %= MOD

    result = 0
    for i in range(1, n + 1):
        for r1 in range(1, i + 1):
            for j in range(1, m + 1):
                for r2 in range(1, j + 1):
                    if x[i - r1] != y[j - r2]:
                        result += dp[r1][r2][r2]
                        result %= MOD
    return result

def main():
    import sys
    input = sys.stdin.read().split()
    x = input[0]
    y = input[1]
    print(count_chaotic_merges(x, y))

if __name__ == "__main__":
    main()
